messages.content:
Tool response:
Tool: create_event_type
Description: Create Event Type
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "title": "Name",
          "description": "Name of the event type"
        },
        "duration_minutes": {
          "type": "integer",
          "exclusiveMinimum": 0.0,
          "title": "Duration Minutes",
          "description": "Duration of the event in minutes"
        },
        "location_type": {
          "type": "string",
          "title": "Location Type",
          "description": "Type of location (e.g., 'google_meet')"
        },
        "location_value": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Location Value",
          "description": "Value for the location (e.g., Google Meet link)"
        },
        "availability_days": {
          "type": "integer",
          "exclusiveMinimum": 0.0,
          "title": "Availability Days",
          "description": "Number of days in the future that the event can be booked"
        },
        "payment_required": {
          "type": "boolean",
          "title": "Payment Required",
          "description": "Whether payment is required to book the event"
        },
        "payment_amount_cents": {
          "anyOf": [
            {
              "type": "integer",
              "minimum": 0.0
            },
            {
              "type": "null"
            }
          ],
          "title": "Payment Amount Cents",
          "description": "Amount to charge in cents"
        },
        "payment_currency": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Payment Currency",
          "description": "Currency for the payment"
        },
        "payment_provider": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Payment Provider",
          "description": "Payment provider (e.g., 'stripe')"
        },
        "reminder_enabled": {
          "type": "boolean",
          "title": "Reminder Enabled",
          "description": "Whether to enable automated reminder emails"
        },
        "reminder_minutes_before": {
          "anyOf": [
            {
              "type": "integer",
              "exclusiveMinimum": 0.0
            },
            {
              "type": "null"
            }
          ],
          "title": "Reminder Minutes Before",
          "description": "Minutes before the event to send the reminder"
        }
      },
      "required": [
        "name",
        "duration_minutes",
        "location_type",
        "availability_days",
        "payment_required",
        "reminder_enabled"
      ]
    }
